#!/usr/bin/env python3
"""Run Quest input regressions without ROS, the native SDK, devices or C++."""

import importlib.util
from pathlib import Path
import sys
import unittest


DEMO = Path(__file__).resolve().parents[1]


def main():
    # All generated bytecode stays below demo/, including when run from elsewhere.
    sys.pycache_prefix = str(DEMO / "build" / "offline" / "pycache")
    package = DEMO / "src" / "xrt_teleop"
    sys.path.insert(0, str(package))
    suite = unittest.TestSuite()
    for filename, case in (("test_xrt_adapter.py", "XrtAdapterTest"),
                           ("test_bridge_freshness.py", "BridgeFreshnessTest"),
                           ("test_input_probe.py", "InputProbeTest")):
        name = "offline_quest_" + filename[:-3]
        spec = importlib.util.spec_from_file_location(name, package / "test" / filename)
        module = importlib.util.module_from_spec(spec)
        sys.modules[name] = module
        spec.loader.exec_module(module)
        suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(getattr(module, case)))
    print("Quest input offline check: fake SDK and ROS messages only; no device calls.", flush=True)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    if result.wasSuccessful():
        print("PASS: reference getter values -> Joy; short presses visible; invalid reads stay invalid.")
        print("Physical Quest/PC-service input reception is not tested by this script.")
    return 0 if result.wasSuccessful() else 1


if __name__ == "__main__":
    sys.exit(main())
